// src/lib/k3FormGorselleri.ts
//
// K3 (Gönderen – Paketleyen – Yükleyen – Dolduran Kontrol Dökümanı)
// formunun ORİJİNAL docx'ten LibreOffice ile birebir (tasarım, görseller,
// tablo hücre birleşimleri korunarak) PDF'e çevrilip 150 DPI PNG olarak
// dışa aktarılmış hâli — her sayfa TasimaEvraki.tsx'te arka plan görseli
// olarak kullanılır, otomatik doldurulacak veriler bu görselin ÜZERİNE
// (ölçülmüş koordinatlarda) yazılır.
//
// Bu dosya TasimaEvraki.tsx'ten DİNAMİK import edilir (await import(...))
// — ana sayfa yükünü artırmasın diye, yalnızca PDF üretilirken yüklenir.
//
// NOT: base64 verisi bilinçli olarak TEK SATIR (chunk'lanmamış) tutulur —
// çok sayıda "+" ile birleştirilmiş küçük parçalar (önceki deneme) build
// sürecinde bir regex/AST işleminin aşırı yavaşlayıp bellek taşırmasına
// (RangeError: Maximum call stack size exceeded, OOM) yol açtı.

export const K3_FORM_SAYFA1 =
  "data:image/png;base64,";

export const K3_FORM_SAYFA2 =
  "data:image/png;base64,";

